import json,gzip
from pathlib import Path
p=Path('research/latest_death_frames_20261001');a=json.load(gzip.open(p/'page_0_box.json.gz','rt'));fs=a['frames'];end=fs[-1]['t'];chosen=[min(fs,key=lambda f:abs(f['t']-(end-d))) for d in [2,1.5,1,.5,.2,0]]
data=[{k:f.get(k) for k in ['t','x','y','ang','sc','L','boost','segs','sid','own','food']} for f in chosen]
h='''<!doctype html><html lang="ko"><meta charset="utf-8"><title>마지막 사망 직전 6프레임</title><style>body{background:#101722;color:#e8edf3;font:15px system-ui;margin:20px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}canvas{width:100%;background:#080d14}h1{font-size:22px}small{color:#afbdce}</style><h1>마지막 사망 판 · 직전 6프레임</h1><p>144.4초 판 · 저장 좌표 재구성 (실제 스크린샷 아님)</p><small>노랑: 우리 몸·머리 / 색상별 선: 적 몸통 / 흰 화살표: 머리 방향 · 모든 프레임 같은 좌표·배율</small><div class="grid" id="grid"></div><script>const frames=DATA,last=frames.at(-1);for(const f of frames){const e=document.createElement('section');e.innerHTML=`<p>${f.t.toFixed(3)}초 · 마지막 관측 ${ (last.t-f.t).toFixed(2)}초 전 · 길이 ${f.L} · 부스트 ${f.boost?'ON':'OFF'}</p><canvas width="900" height="650"></canvas>`;grid.append(e);const c=e.querySelector('canvas'),g=c.getContext('2d'),scale=.7,X=x=>450+(x-last.x)*scale,Y=y=>325+(y-last.y)*scale;g.lineCap='round';for(let i=0;i<f.segs.length;i+=5){let s=f.segs;g.strokeStyle=`hsl(${((f.sid?.[i/5]||0)*137.5)%360} 55% 55%)`;g.lineWidth=2*s[i+4]*scale;g.beginPath();g.moveTo(X(s[i]),Y(s[i+1]));g.lineTo(X(s[i+2]),Y(s[i+3]));g.stroke()}g.fillStyle='#e7bd78';for(let i=0;i<(f.food||[]).length;i+=3){g.beginPath();g.arc(X(f.food[i]),Y(f.food[i+1]),2,0,7);g.fill()}g.strokeStyle='#ffe479';g.lineWidth=29*f.sc*scale;g.beginPath();for(let i=0;i<(f.own||[]).length;i+=2){i?g.lineTo(X(f.own[i]),Y(f.own[i+1])):g.moveTo(X(f.own[i]),Y(f.own[i+1]))}g.stroke();g.fillStyle='#fff3ad';g.beginPath();g.arc(X(f.x),Y(f.y),8,0,7);g.fill();g.strokeStyle='white';g.lineWidth=3;g.beginPath();g.moveTo(X(f.x),Y(f.y));g.lineTo(X(f.x)+40*Math.cos(f.ang),Y(f.y)+40*Math.sin(f.ang));g.stroke()}</script></html>'''
(p/'frames.html').write_text(h.replace('DATA',json.dumps(data)))
(p/'selection.json').write_text(json.dumps({'record_seconds':a['seconds'],'build':a['ext'],'last_observation':end,'selected_times':[f['t'] for f in chosen]},indent=2))
print((p/'selection.json').read_text())
